-- Create staging_company_skill_levels table
DROP TABLE IF EXISTS staging_company_skill_levels;

CREATE TABLE staging_company_skill_levels (
  id                                      integer PRIMARY KEY,
  companies                               text,
  coding                                  text,
  data_structures_and_algorithms          text,
  object_oriented_programming_and_design  text,
  aptitude_and_problem_solving            text,
  communication_skills                    text,
  ai_native_engineering                   text,
  devops_and_cloud                        text,
  sql_and_design                          text,
  software_engineering                    text,
  system_design_and_architecture          text,
  computer_networking                     text,
  operating_system                        text,
  processed                               text,
  processed_at                            timestamptz,
  error_message                           text,
  created_at                              timestamptz
);

-- Allow the service role (used by backend) to SELECT
GRANT SELECT ON staging_company_skill_levels TO service_role;
-- Also allow anon for PostgREST reads with the anon key if needed
GRANT SELECT ON staging_company_skill_levels TO anon, authenticated;

